// Deterministic generator of a realistic multi-turn Arena coding-session
// transcript in exported Markdown form. 100% synthetic: every file, test,
// issue and command below is invented for this fixture (fictional
// `widget-service` project, `example` GitHub org). No private repository or
// transcript text is reproduced here.
//
// Shape (target ~500 KB, measured in UTF-8 bytes):
//   ~27% Thought blocks (multi-paragraph `#### Thought for Ns` prose),
//   ~45% stdout (cat -n / sed -n / grep -rn / pytest dot-runs / GitHub REST
//     JSON / wide single lines / chunked stdout cards / errors),
//   ~20% command (including `python3 - <<'PY'` heredocs and compound
//     commands that `commandInfo()` currently rejects),
//   ~8% framing (header, headings, labels, fences) and User / final
//     Assistant prose.
//
// The workload deliberately exercises the bottlenecks from the compression
// epic: pytest dot-progress (missed by PASS_PATTERNS), wide grep output,
// REST/GraphQL boilerplate, overlapping cat -n vs sed -n reads (Stubs
// candidates), identical re-reads (Lossless candidates), inline heredoc
// scripts, chunked stdout cards, and exit != 0 / traceback diagnostics that
// must survive every mode verbatim.
//
// Deterministic: no randomness, no wall-clock input. Two calls always return
// byte-identical Markdown. Use `generateSyntheticCodingSession()` for the
// benchmark; `extractInvariants()` / `sessionByteShares()` are generic
// Arena-Markdown parsers shared by the benchmark and tests.

const FENCE = String.fromCharCode(96).repeat(3);
const NL = String.fromCharCode(10);

const fence = (body, lang = 'text') => FENCE + lang + NL + body + NL + FENCE;
const commandBlock = command => '**command:**' + NL + NL + fence('$ ' + command, 'bash');
const stdoutBlock = body => '**stdout:**' + NL + NL + fence(body);
const stderrBlock = body => '**stderr:**' + NL + NL + fence(body);

const thoughtBlock = (seconds, paragraphs) =>
  '#### Thought for ' + seconds + 's' + NL + NL + paragraphs.join(NL + NL);

const bashRun = ({ heading, command, stdout, stderr }) => {
  const parts = ['##### used Bash ' + heading, commandBlock(command)];
  if (stdout != null) parts.push(stdoutBlock(stdout));
  if (stderr != null) parts.push(stderrBlock(stderr));
  return parts.join(NL + NL);
};

const ranGroup = runs => '#### Ran commands ' + runs.length + NL + NL + runs.join(NL + NL);

// ---------------------------------------------------------------------------
// Size tuning (single place to adjust the fixture's byte profile).
// ---------------------------------------------------------------------------

const SIZES = {
  widgetLines: 150, // lines in the main source file read by cat -n
  clientLines: 60, // lines in the downstream client read
  configLines: 80, // lines in a config module read
  helperLines: 45, // lines in a generated helper file read
  grepLines: 46, // matches per grep -rn run
  restIssues: 9, // issue objects per REST JSON response
  graphqlItems: 40, // items in the single-line GraphQL response
  buildLogLines: 150, // lines per build log
  thoughtParagraphs: 16, // paragraphs per Thought block
  // Command mix: heredoc script invocations across the session.
  heredocs: { refactor: 7, testgen: 5, json: 6, doc: 5, patch: 4, inspect: 4 },
};

// ---------------------------------------------------------------------------
// Source-file bodies (fictional widget-service code, generated by index).
// ---------------------------------------------------------------------------

function widgetPyLines(count, { variant = 0 } = {}) {
  const lines = [];
  lines.push('"""Widget service: request handling and retry policy."""');
  lines.push('import json');
  lines.push('import time');
  lines.push('from dataclasses import dataclass, field');
  lines.push('');
  lines.push('MAX_RETRIES = 3');
  lines.push('RETRY_DELAY_S = 0.5');
  lines.push('SIZE_LIMIT = 1024');
  lines.push('');
  lines.push('');
  lines.push('class WidgetError(Exception):');
  lines.push('    """Raised when a widget request cannot be completed."""');
  lines.push('    pass');
  lines.push('');
  lines.push('');
  lines.push('@dataclass');
  lines.push('class WidgetRequest:');
  lines.push('    size: int');
  lines.push('    variant: int = 1');
  lines.push('    tags: list = field(default_factory=list)');
  lines.push('');
  lines.push('');
  lines.push('class WidgetService:');
  lines.push('    def __init__(self, client, timeout_s=30):');
  lines.push('        self.client = client');
  lines.push('        self.timeout_s = timeout_s');
  lines.push('        self.error_count = 0');
  lines.push('        self.pointError = None');
  lines.push('');
  for (let i = 0; i < count; i += 1) {
    const n = i + 1;
    if (variant === 1 && n === 42) {
      lines.push('    def handle_request_v2(self, payload):  # revised retry path');
    } else if (variant === 1 && n === 43) {
      lines.push('        # error handling: retry once on transient failure');
    } else if (n % 7 === 0) {
      lines.push('    def handle_request_' + n + '(self, payload):');
      lines.push('        """Handle widget request variant ' + n + '."""');
      lines.push('        if payload is None:');
      lines.push('            raise WidgetError("empty payload for variant ' + n + '")');
      lines.push('        return self._dispatch(payload, variant=' + n + ')');
    } else if (n % 5 === 0) {
      lines.push('    def _dispatch(self, payload, variant=' + n + '):');
      lines.push('        # dispatch variant ' + n + ' to the downstream client');
      lines.push('        return self.client.send(payload, timeout=self.timeout_s)');
    } else if (n % 3 === 0) {
      lines.push('    def _validate_' + n + '(self, payload):');
      lines.push('        size = payload.get("size", 0)');
      lines.push('        if size < 0 or size > SIZE_LIMIT:');
      lines.push('            raise WidgetError("invalid widget size: %r" % (size,))');
      lines.push('        return True');
    } else {
      lines.push('    def _normalize_' + n + '(self, payload):');
      lines.push('        # normalize widget payload for variant ' + n);
      lines.push('        return {k: v for k, v in payload.items() if v is not None}');
    }
  }
  lines.push('');
  lines.push('    def run(self, payload):');
  lines.push('        for attempt in range(MAX_RETRIES):');
  lines.push('            try:');
  lines.push('                return self.handle_request_1(payload)');
  lines.push('            except WidgetError:');
  lines.push('                self.error_count += 1');
  lines.push('                if attempt == MAX_RETRIES - 1:');
  lines.push('                    raise');
  lines.push('                time.sleep(RETRY_DELAY_S * (attempt + 1))');
  lines.push('        raise WidgetError("unreachable")');
  return lines;
}

function numbered(lines) {
  return lines.map((line, i) => String(i + 1).padStart(4, ' ') + '\t' + line).join(NL);
}

function clientPyLines(count) {
  const lines = [];
  lines.push('"""Downstream HTTP client used by WidgetService."""');
  lines.push('import json');
  lines.push('import urllib.request');
  lines.push('import urllib.error');
  lines.push('');
  lines.push('');
  lines.push('class DownstreamClient:');
  lines.push('    def __init__(self, base_url):');
  lines.push('        self.base_url = base_url.rstrip("/")');
  lines.push('        self.request_count = 0');
  lines.push('');
  for (let i = 0; i < count; i += 1) {
    const n = i + 1;
    lines.push('    def send_' + n + '(self, payload, timeout=30):');
    lines.push('        """Send variant ' + n + ' payload to the downstream API."""');
    lines.push('        self.request_count += 1');
    lines.push('        body = json.dumps(payload).encode("utf-8")');
    lines.push('        req = urllib.request.Request(self.base_url + "/widgets", data=body)');
    lines.push('        req.add_header("Content-Type", "application/json")');
    lines.push('        with urllib.request.urlopen(req, timeout=timeout) as resp:');
    lines.push('            return json.loads(resp.read().decode("utf-8"))');
    lines.push('');
  }
  return lines;
}

function configPyLines(count) {
  const lines = [];
  lines.push('"""Runtime configuration for the widget service."""');
  lines.push('import os');
  lines.push('');
  lines.push('');
  lines.push('def _env(name, default):');
  lines.push('    val = os.environ.get(name)');
  lines.push('    return val if val is not None else default');
  lines.push('');
  lines.push('');
  lines.push('class Settings:');
  lines.push('    def __init__(self):');
  lines.push('        self.base_url = _env("WIDGET_BASE_URL", "https://api.example.invalid")');
  lines.push('        self.timeout_s = int(_env("WIDGET_TIMEOUT", "30"))');
  lines.push('        self.max_retries = int(_env("WIDGET_MAX_RETRIES", "3"))');
  lines.push('        self.feature_flags = {}');
  lines.push('');
  for (let i = 0; i < count; i += 1) {
    const n = i + 1;
    lines.push('    def flag_' + n + '(self):');
    lines.push('        """Feature flag ' + n + ' for widget handling."""');
    lines.push('        return self.feature_flags.get("flag_' + n + '", False)');
    lines.push('');
  }
  lines.push('    def validate(self):');
  lines.push('        if self.timeout_s <= 0:');
  lines.push('            raise ValueError("timeout must be positive")');
  lines.push('        if self.max_retries < 1:');
  lines.push('            raise ValueError("max_retries must be at least 1")');
  lines.push('        return True');
  return lines;
}

