function thoughtParagraphs(topicIndex, paragraphCount) {
  const paragraphs = [];
  for (let p = 0; p < paragraphCount; p += 1) {
    const base = THOUGHT_TOPICS[(topicIndex + p) % THOUGHT_TOPICS.length][0];
    // Vary length deterministically so Thoughts are multi-paragraph and
    // multi-KB without any randomness.
    const suffix = ' Observation ' + (p + 1) + ': I will verify this against the next tool output before acting on it, and I will keep the change minimal so the diff stays reviewable.';
    paragraphs.push(base + suffix);
  }
  return paragraphs;
}

// ---------------------------------------------------------------------------
// stdout builders.
// ---------------------------------------------------------------------------

function grepStdout() {
  const lines = [];
  const files = ['src/widget.py', 'src/client.py', 'tests/test_widget.py', 'tests/test_api.py'];
  for (let f = 0; f < files.length; f += 1) {
    for (let i = 0; i < SIZES.grepLines / files.length; i += 1) {
      const lineNo = 12 + f * 37 + i * 9;
      const fn = ['handle_request', '_dispatch', '_validate', '_normalize', 'send'][i % 5] + '_' + (i + 1);
      const tail = '  # widget request handler for downstream dispatch with retry and timeout handling';
      lines.push(files[f] + ':' + lineNo + ':    def ' + fn + '(self, payload, timeout_s=30):' + tail);
    }
  }
  lines.push('src/widget.py:18:        self.error_count = 0  # tracks failures across retries');
  lines.push('src/widget.py:19:        self.pointError = None  # last error seen by this service instance');
  lines.push('tests/test_widget.py:44:    # error path: invalid size must raise WidgetError');
  return lines.join(NL);
}

function pytestDotStdout({ total = 84, failedIndex = -1 } = {}) {
  const lines = [];
  const files = ['tests/test_widget.py', 'tests/test_api.py', 'tests/test_client.py'];
  const perFile = Math.ceil(total / files.length);
  let done = 0;
  for (let f = 0; f < files.length; f += 1) {
    const dots = [];
    for (let i = 0; i < perFile && done < total; i += 1, done += 1) {
      dots.push(done === failedIndex ? 'F' : '.');
    }
    const pct = Math.round(((f + 1) * perFile / total) * 100);
    lines.push(files[f] + ' ' + dots.join('') + ' [' + String(pct).padStart(3, ' ') + '%]');
  }
  if (failedIndex >= 0) {
    lines.push('FAILED tests/test_widget.py::test_invalid_size - ValueError: invalid widget size');
    lines.push('1 failed, ' + (total - 1) + ' passed in 12.34s');
  } else {
    lines.push('==================== ' + total + ' passed in 11.87s ====================');
  }
  return lines.join(NL);
}

function pytestVerboseStdout(start, count) {
  const lines = [];
  for (let i = start; i < start + count; i += 1) {
    lines.push('tests/test_widget.py::test_case_' + i + ' PASSED [ 1%]');
  }
  lines.push('tests/test_widget.py::test_invalid_size FAILED [ 99%]');
  lines.push('1 failed, ' + (count - 1) + ' passed in 14.02s');
  return lines.join(NL);
}

function pytestCheckStdout() {
  const lines = [];
  for (let i = 0; i < 14; i += 1) {
    lines.push('✓ suite > widget test-' + i + ' [1.00ms]');
  }
  lines.push('14 passed in 0.42s');
  return lines.join(NL);
}

function restJsonStdout() {
  const issues = [];
  for (let i = 0; i < SIZES.restIssues; i += 1) {
    const n = 101 + i;
    issues.push(
      '  {',
      '    "url": "https://api.github.com/repos/example/widget-service/issues/' + n + '",',
      '    "repository_url": "https://api.github.com/repos/example/widget-service",',
      '    "labels_url": "https://api.github.com/repos/example/widget-service/issues/' + n + '/labels{/name}",',
      '    "comments_url": "https://api.github.com/repos/example/widget-service/issues/' + n + '/comments",',
      '    "events_url": "https://api.github.com/repos/example/widget-service/issues/' + n + '/events",',
      '    "html_url": "https://github.com/example/widget-service/issues/' + n + '",',
      '    "id": ' + (900000 + i) + ',',
      '    "node_id": "I_kwDOExample' + n + '",',
      '    "number": ' + n + ',',
      '    "title": "Widget retry policy needs jitter for variant ' + n + '",',
      '    "state": "' + (i % 3 === 0 ? 'open' : 'closed') + '",',
      '    "labels": [{"name": "enhancement"}],',
      '    "assignee": null,',
      '    "author_association": "NONE"',
      '  }' + (i < SIZES.restIssues - 1 ? ',' : '')
    );
  }
  return '[' + NL + issues.join(NL) + NL + ']';
}

function graphqlSingleLineStdout() {
  const parts = [];
  for (let i = 0; i < SIZES.graphqlItems; i += 1) {
    parts.push('{"node":{"id":"IC_example' + i + '","title":"Widget variant ' + i + '","state":"OPEN","url":"https://github.com/example/widget-service/issues/' + (200 + i) + '"}}');
  }
  return '{"data":{"repository":{"issues":[' + parts.join(',') + ']}}}';
}

function tracebackStdout() {
  return [
    'Traceback (most recent call last):',
    '  File "src/widget.py", line 87, in handle',
    '    raise ValueError("invalid widget size")',
    'ValueError: invalid widget size',
    'FAILED tests/test_widget.py::test_invalid_size - ValueError: invalid widget size',
  ].join(NL);
}

function buildLogStdout(count) {
  const lines = [];
  for (let i = 0; i < count; i += 1) {
    lines.push('build step ' + i + ' completed');
  }
  return lines.join(NL);
}

