function heredocJsonScript() {
  const lines = [
    "python3 - <<'PY'",
    '"""Project a GitHub REST issue payload down to title and state."""',
    'import json',
    'import sys',
    '',
    'payload = json.loads(sys.stdin.read())',
    '',
    'def project(issue):',
    '    """Keep only the fields needed for the retry-issue list."""',
    '    return {',
    '        "number": issue.get("number"),',
    '        "title": issue.get("title"),',
    '        "state": issue.get("state"),',
    '        "labels": [label.get("name") for label in issue.get("labels", [])],',
    '        "comments": issue.get("comments", 0),',
    '    }',
    '',
    'projected = [project(issue) for issue in payload]',
    '',
    '# Stability pass: sort by number so repeated runs diff cleanly.',
    'projected.sort(key=lambda item: item.get("number") or 0)',
    '',
    '# Filter pass: keep only issues that mention retry in the title.',
    'retry_issues = [item for item in projected if "retry" in (item.get("title") or "").lower()]',
    '',
    'print(json.dumps(projected, indent=2))',
    'print("retry-related:", len(retry_issues), "of", len(projected))',
    '',
    '# Extra pass: group the projected issues by state for a quick count.',
    'by_state = {}',
    'for item in projected:',
    '    state = item.get("state", "unknown")',
    '    by_state[state] = by_state.get(state, 0) + 1',
    'print("by state:", json.dumps(by_state, sort_keys=True))',
    '',
    '# Extra pass: list the labels used across all issues.',
    'all_labels = sorted({label for item in projected for label in item.get("labels", [])})',
    'print("labels:", json.dumps(all_labels))',
    '',
    '# Extra pass: flag issues with comments above the median.',
    'counts = sorted(item.get("comments", 0) for item in projected)',
    'median = counts[len(counts) // 2] if counts else 0',
    'busy = [item["number"] for item in projected if item.get("comments", 0) > median]',
    'print("busy issues:", json.dumps(busy))',
    'PY',
  ];
  return lines.join(NL);
}

