function heredocPatchScript() {
  const lines = [
    "python3 - <<'PY'",
    '"""Apply the one-line delay documentation patch with guard checks."""',
    'from pathlib import Path',
    '',
    'target = Path("src/widget.py")',
    'text = target.read_text()',
    '',
    '# Guard: the anchor must exist exactly once before patching.',
    'count = text.count("RETRY_DELAY_S = 0.5")',
    'assert count == 1, "expected exactly one delay anchor, found " + str(count)',
    '',
    'old = "RETRY_DELAY_S = 0.5"',
    'new = "RETRY_DELAY_S = 0.5  # seconds; jitter added in run()"',
    'patched = text.replace(old, new, 1)',
    '',
    '# Guard: the replacement must not touch anything else.',
    'assert patched.count("RETRY_DELAY_S = 0.5  # seconds; jitter added in run()") == 1',
    'assert patched.count("MAX_RETRIES = 3") == text.count("MAX_RETRIES = 3")',
    '',
    '# Extra guard: verify the file still parses after the patch.',
    'import ast',
    'ast.parse(patched)',
    '',
    '# Extra guard: verify the patch did not duplicate the comment.',
    'assert patched.count("# seconds; jitter added in run()") == 1, "duplicate comment"',
    '',
    '# Extra guard: report the exact line count before and after.',
    'print("line count:", len(text.splitlines()), "->", len(patched.splitlines()))',
    '',
    'target.write_text(patched)',
    'print("patched src/widget.py: delay constant documented")',
    'PY',
  ];
  return lines.join(NL);
}

function heredocInspectScript() {
  const lines = [
    "python3 - <<'PY'",
    '"""Dump the public surface of widget.py for review."""',
    'import ast',
    'import pathlib',
    '',
    'tree = ast.parse(pathlib.Path("src/widget.py").read_text())',
    '',
    'print("module docstring:", ast.get_docstring(tree))',
    'print("")',
    'print("top-level constants:")',
    'for node in tree.body:',
    '    if isinstance(node, ast.Assign):',
    '        for target in node.targets:',
    '            if isinstance(target, ast.Name):',
    '                print("  ", target.id, "=", ast.dump(node.value)[:60])',
    'print("")',
    'print("functions and their first line:")',
    'for node in ast.walk(tree):',
    '    if isinstance(node, ast.FunctionDef):',
    '        print("  ", node.name, node.lineno)',
    'print("")',
    'print("classes and their methods:")',
    'for node in tree.body:',
    '    if isinstance(node, ast.ClassDef):',
    '        print("  ", node.name)',
    '        for sub in node.body:',
    '            if isinstance(sub, ast.FunctionDef):',
    '                print("      ", sub.name, sub.lineno)',
    'print("")',
    'print("imports:")',
    'for node in ast.walk(tree):',
    '    if isinstance(node, ast.Import):',
    '        for alias in node.names:',
    '            print("  ", alias.name)',
    '    elif isinstance(node, ast.ImportFrom):',
    '        print("  from", node.module, "import", ", ".join(a.name for a in node.names))',
    'print("")',
    'print("module-level assignments:")',
    'for node in tree.body:',
    '    if isinstance(node, ast.Assign):',
    '        print("  line", node.lineno, ast.dump(node.value)[:80])',
    'print("")',
    'print("docstring:", ast.get_docstring(tree))',
    'PY',
  ];
  return lines.join(NL);
}

function compoundLoopCommand(label) {
  const lines = ['cd /repo && for f in src/*.py tests/*.py; do'];
  lines.push('  echo "== $f"');
  lines.push('  wc -l "$f"');
  lines.push('  grep -c "def " "$f" || true');
  lines.push('  grep -c "class " "$f" || true');
  lines.push('  grep -n "raise " "$f" | head -5 || true');
  lines.push('done | sed -n "1,80p"  # ' + label);
  return lines.join(NL);
}

function longGrepCommand() {
  const patterns = [];
  for (let i = 0; i < 12; i += 1) {
    patterns.push('-e "Widget" -e "widget" -e "retry" -e "RETRY" -e "timeout" -e "error_count"');
  }
  return 'grep -rn ' + patterns.join(' ') + ' src/ tests/ docs/ 2>/dev/null | head -200';
}

function longSedCommand() {
  const exprs = [];
  for (let i = 0; i < 10; i += 1) {
    const a = 1 + i * 13;
    exprs.push(a + ',' + (a + 12) + 'p');
  }
  return "sed -n " + exprs.map(e => "'" + e + "'").join(' ') + ' src/widget.py';
}

