export function generateSyntheticCodingSession() {
  const turns = buildTurns();
  const header = [
    '# ' + SYNTHETIC_SESSION_META.title,
    '',
    '- Source: ' + SYNTHETIC_SESSION_META.source,
    '- Exported: ' + SYNTHETIC_SESSION_META.exported,
    '- Messages: ' + turns.length,
    '',
    '---',
  ].join(NL);
  return [header, ...turns].join(NL + NL) + NL;
}

// ---------------------------------------------------------------------------
// Generic Arena-Markdown parsers (shared by benchmark + tests).
// ---------------------------------------------------------------------------

const HEADING_RE = /^## (👤 User|🤖 Assistant)\s*$/m;

export function splitSections(markdown) {
  const sections = [];
  const re = /^## (👤 User|🤖 Assistant)\s*$/gm;
  let match;
  let lastIndex = 0;
  let lastKind = null;
  while ((match = re.exec(markdown)) !== null) {
    if (lastKind !== null) {
      sections.push({ kind: lastKind, body: markdown.slice(lastIndex, match.index).trim() });
    }
    lastKind = match[1] === '👤 User' ? 'user' : 'assistant';
    lastIndex = re.lastIndex;
  }
  if (lastKind !== null) {
    sections.push({ kind: lastKind, body: markdown.slice(lastIndex).trim() });
  }
  return sections;
}

// Trailing prose of the last Assistant section: text after the final fenced
// block. Returns '' when the last Assistant section ends with a tool block.
export function finalAssistantProse(markdown) {
  const sections = splitSections(markdown);
  for (let i = sections.length - 1; i >= 0; i -= 1) {
    if (sections[i].kind !== 'assistant') continue;
    const body = sections[i].body;
    const lines = body.split(NL);
    for (let j = lines.length - 1; j >= 0; j -= 1) {
      if (lines[j] === FENCE) {
        return lines.slice(j + 1).join(NL).trim();
      }
    }
    return body.trim();
  }
  return '';
}

const DIAGNOSTIC_LINE_RE = /^(Traceback \(most recent call last\):|\s*File ".+", line \d+, in .+|(?:AssertionError|ValueError|TypeError|KeyError|RuntimeError|ImportError|ModuleNotFoundError|OSError|Exception): .+|FAILED .+|cat: .+No such file or directory)$/;

// Must-preserve diagnostic lines: traceback / exception / FAILED / missing-file
// lines anywhere in the document, plus every non-empty stderr fence body.
export function diagnosticLines(markdown) {
  const lines = [];
  for (const line of markdown.split(NL)) {
    if (DIAGNOSTIC_LINE_RE.test(line)) lines.push(line);
  }
  const stderrRe = /\*\*stderr:\*\*\s*\n\n```[^\n]*\n([\s\S]*?)\n```/g;
  let match;
  while ((match = stderrRe.exec(markdown)) !== null) {
    const body = match[1].trim();
    if (body) lines.push(body);
  }
  return lines;
}

export function exitHeadings(markdown) {
  return markdown.split(NL).filter(line => /^#{4,5} used Bash exit \d+ /.test(line));
}

export function extractInvariants(markdown) {
  const sections = splitSections(markdown);
  return {
    userTurns: sections.filter(s => s.kind === 'user').map(s => s.body),
    userHeadingCount: sections.filter(s => s.kind === 'user').length,
    assistantHeadingCount: sections.filter(s => s.kind === 'assistant').length,
    finalAssistant: finalAssistantProse(markdown),
    diagnostics: diagnosticLines(markdown),
    exitHeadings: exitHeadings(markdown),
  };
}

// Byte shares by category. Fence bodies count toward stdout/command/stderr;
// Thought sections (heading + prose) toward thought; everything else
// (header, headings, labels, fences, User turns, final prose) toward framing.
export function sessionByteShares(markdown) {
  const enc = new TextEncoder();
  const totalBytes = enc.encode(markdown).length;
  let thoughtBytes = 0;
  let stdoutBytes = 0;
  let commandBytes = 0;
  let stderrBytes = 0;

  // Thought sections: from `#### Thought` heading to the next heading.
  const lines = markdown.split(NL);
  let inThought = false;
  let thoughtBuf = [];
  const flushThought = () => {
    if (inThought && thoughtBuf.length) {
      thoughtBytes += enc.encode(thoughtBuf.join(NL)).length;
    }
    thoughtBuf = [];
  };
  for (const line of lines) {
    if (/^#{2,6}\s+/.test(line)) {
      flushThought();
      inThought = /^#### Thought for /.test(line);
      if (inThought) thoughtBuf.push(line);
      continue;
    }
    if (inThought) thoughtBuf.push(line);
  }
  flushThought();

  const fenceRe = /\*\*(stdout|command|stderr):\*\*\s*\n\n```[^\n]*\n([\s\S]*?)\n```/g;
  let match;
  while ((match = fenceRe.exec(markdown)) !== null) {
    const bytes = enc.encode(match[2]).length;
    if (match[1] === 'stdout') stdoutBytes += bytes;
    else if (match[1] === 'command') commandBytes += bytes;
    else stderrBytes += bytes;
  }

  const framingBytes = Math.max(0, totalBytes - thoughtBytes - stdoutBytes - commandBytes - stderrBytes);
  const share = bytes => (totalBytes ? bytes / totalBytes : 0);
  return {
    totalBytes,
    thoughtBytes,
    stdoutBytes,
    commandBytes,
    stderrBytes,
    framingBytes,
    thoughtShare: share(thoughtBytes),
    stdoutShare: share(stdoutBytes + stderrBytes),
    commandShare: share(commandBytes),
    framingShare: share(framingBytes),
  };
}
